from fractions import Fraction


def option_value(kind, strike):
    """Fair value of a "call", "put" or "straddle" on the
    sum of two dice, as a Fraction."""
    total = 0
    for a in range(1, 7):
        for b in range(1, 7):
            s = a + b
            c, p = max(s - strike, 0), max(strike - s, 0)
            total += {"call": c, "put": p, "straddle": c + p}[kind]
    return Fraction(total, 36)


def parity_gap(call_q, put_q, sum_q, strike):
    """Each quote is (bid, ask). Return the locked profit of
    the better parity trade, or Fraction(0) if neither pays."""
    # sell call, buy put, buy sum: pays strike
    a = strike - (put_q[1] + sum_q[1] - call_q[0])
    # buy call, sell put, sell sum: pays -strike
    b = put_q[0] + sum_q[0] - call_q[1] - strike
    return max(Fraction(0), a, b)
